document.getElementById('year').textContent=new Date().getFullYear();
const menu=document.querySelector('.menu');const nav=document.querySelector('nav');
menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');menu.textContent=open?'×':'☰';});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='☰';}));
document.getElementById('project-form').addEventListener('submit',async e=>{e.preventDefault();const data=new FormData(e.currentTarget);const brief=`SPROUT TECH — PROJECT BRIEF\n\nName: ${data.get('name')}\nEmail: ${data.get('email')}\n\nThe idea:\n${data.get('idea')}`;const result=document.getElementById('form-result');result.hidden=false;result.replaceChildren();const title=document.createElement('strong');title.textContent='Your project brief is ready.';const copy=document.createElement('button');copy.type='button';copy.className='button';copy.textContent='Copy project brief';copy.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(brief);copy.textContent='Copied ✓';}catch{copy.textContent='Select and copy the brief below';}});const content=document.createElement('p');content.textContent=brief;result.append(title,content,copy);});
